        .route("/_config", get(config_handler))
}

/// Standard Handler (all tools)
async fn mcp_handler(
    Extension(state): Extension<Arc<AppState>>,
    Json(request): Json<McpRequest>,
) -> Json<McpResponse> {
    let response = process_request(&state, request).await;
    Json(response)
}

